package places

import (
	_ "embed"
	"encoding/json"
	"math"
	"sync"
)

// japan_prefectures.json is generated by scripts/build_japan_map.py and is the
// same geometry the app draws, so a spot's prefecture always matches the map.
//
//go:embed japan_prefectures.json
var prefectureGeometry []byte

type prefectureShape struct {
	Code    string `json:"code"`
	Name    string `json:"name"`
	NameJa  string `json:"nameJa"`
	Capital struct {
		Name string  `json:"name"`
		Lat  float64 `json:"lat"`
		Lng  float64 `json:"lng"`
	} `json:"capital"`
	Polygons [][][2]float64 `json:"polygons"`
}

var (
	prefecturesOnce sync.Once
	prefectures     []prefectureShape
)

func loadPrefectures() []prefectureShape {
	prefecturesOnce.Do(func() {
		var data struct {
			Prefectures []prefectureShape `json:"prefectures"`
		}
		if err := json.Unmarshal(prefectureGeometry, &data); err != nil {
			panic("places: invalid japan_prefectures.json: " + err.Error())
		}
		prefectures = data.Prefectures
	})
	return prefectures
}

// ValidPrefecture reports whether code is one of "01".."47".
func ValidPrefecture(code string) bool {
	for _, p := range loadPrefectures() {
		if p.Code == code {
			return true
		}
	}
	return false
}

// PrefectureAt returns the prefecture containing the point. Points outside every
// simplified outline (small islands, coastlines) use the nearest outline within
// about 30 km; anything farther returns "".
func PrefectureAt(lat, lng float64) string {
	best, bestDistance := "", math.Inf(1)
	for _, p := range loadPrefectures() {
		for _, ring := range p.Polygons {
			if containsPoint(ring, lng, lat) {
				return p.Code
			}
			if d := ringDistance(ring, lng, lat); d < bestDistance {
				best, bestDistance = p.Code, d
			}
		}
	}
	if bestDistance <= 0.3 {
		return best
	}
	return ""
}

func containsPoint(ring [][2]float64, x, y float64) bool {
	inside := false
	for i, j := 0, len(ring)-1; i < len(ring); j, i = i, i+1 {
		xi, yi, xj, yj := ring[i][0], ring[i][1], ring[j][0], ring[j][1]
		if (yi > y) != (yj > y) && x < (xj-xi)*(y-yi)/(yj-yi)+xi {
			inside = !inside
		}
	}
	return inside
}

// ringDistance is the smallest distance in degrees (longitude scaled by
// latitude) from the point to the ring's edges.
func ringDistance(ring [][2]float64, x, y float64) float64 {
	k := math.Cos(y * math.Pi / 180)
	best := math.Inf(1)
	for i := 1; i < len(ring); i++ {
		ax, ay := ring[i-1][0]*k, ring[i-1][1]
		bx, by := ring[i][0]*k, ring[i][1]
		px := x * k
		dx, dy := bx-ax, by-ay
		t := 0.0
		if l := dx*dx + dy*dy; l > 0 {
			t = math.Max(0, math.Min(1, ((px-ax)*dx+(y-ay)*dy)/l))
		}
		cx, cy := ax+t*dx-px, ay+t*dy-y
		best = math.Min(best, math.Hypot(cx, cy))
	}
	return best
}
